    private static void Assert(bool value,string text){if(!value)throw new InvalidOperationException(text);}
    private static async Task Deny(Func<Task> action){try{await action();}catch(Exception e)when(e is InvalidOperationException or UnauthorizedAccessException or DbUpdateConcurrencyException or MediaUploadException){return;}throw new InvalidOperationException("Expected denial.");}
    public static InteractionInput Input()=>new(){Kind=InteractionKind.Inquiry,Name="Người kiểm thử",Email="finish-"+Guid.NewGuid().ToString("N")+"@landportal.invalid",Title="Hồ sơ Test riêng",Text="Nội dung gốc riêng Test",Field="Test",PublicConsent=true};
    public static async Task<string> User(PortalDbContext db,IEnumerable<string> claims,string label)
    {
        var id=Guid.NewGuid().ToString();db.Users.Add(new(){Id=id,UserName="qa-finish-"+id,NormalizedUserName=("qa-finish-"+id).ToUpperInvariant(),Email="qa-"+id+"@landportal.invalid",NormalizedEmail=("qa-"+id+"@landportal.invalid").ToUpperInvariant(),EmailConfirmed=true,SecurityStamp=Guid.NewGuid().ToString(),DisplayName=label});foreach(var p in claims)db.UserClaims.Add(new(){UserId=id,ClaimType="permission",ClaimValue=p});await db.SaveChangesAsync();return id;
    }
    public sealed class Fixture(string root,DbContextOptions<PortalDbContext> options,IConfiguration config,LocalMailSink sink,Clock? clock=null)
    {
        public string Workspace=root;
        public IDataProtectionProvider Protection=DataProtectionProvider.Create(new DirectoryInfo(StorageOptions.FromConfiguration(config).KeysRoot),b=>b.SetApplicationName("LandPortal"));
        public InteractionMailOptions Mail=new(){Available=true,SinkPort=sink.Port};
        public InquiryAttachmentService Files(PortalDbContext db)=>new(db,StorageOptions.FromConfiguration(config),new(db,StorageOptions.FromConfiguration(config),MediaUploadOptions.FromConfiguration(config,"Development")),Protection,new(){Enabled=true},clock);
        public InteractionService Interaction(PortalDbContext db)=>new(db,Protection,Mail,new(db),clock,Files(db));
        public InquiryLookupService Lookup(PortalDbContext db)=>new(db,Protection,Mail,Interaction(db),clock);
        public async Task<InteractionReceipt> Submit(InteractionInput input,string session)
        {
            await using var db=new PortalDbContext(options);var service=Interaction(db);var challenge=await service.RequestAsync(input,session);var mailId=await db.InteractionOutbox.Where(x=>x.ChallengeId==challenge).Select(x=>x.Id).SingleAsync();await new InteractionOutboxService(db,Protection,Mail,new(db),clock).RunOnceAsync(mailId);var code=Regex.Match(sink.Bodies[mailId],@"Mã xác minh: (\d{6})").Groups[1].Value;return await service.SubmitAsync(challenge,input,session,code);
        }
        public async Task<string> Receipt(Guid id)
        {
            await using var db=new PortalDbContext(options);var mailId=await db.InteractionOutbox.Where(x=>x.SubmissionId==id&&x.EventKey.StartsWith("receipt:")).Select(x=>x.Id).SingleAsync();await new InteractionOutboxService(db,Protection,Mail,new(db),clock).RunOnceAsync(mailId);return Regex.Match(sink.Bodies[mailId],@"Mã hồ sơ: ([a-f0-9]{32})").Groups[1].Value;
        }
    }
